import zod from "zod";
const networkRequestLogSchema = zod.object({
    method: zod.string(),
    status: zod.number().int(),
    statusText: zod.string(),
    path: zod.string(),
    requestData: zod.optional(zod.unknown()),
    requestParams: zod.optional(zod.unknown()),
    responseData: zod.optional(zod.unknown()),
    traceID: zod.string()
});
const genericErrorSchema = zod.object({
    message: zod.string(),
    stack: zod.string()
});
const routerErrorSchema = zod.object({
    path: zod.string()
});
const noCategoryLogSchema = zod.object({
    message: zod.unknown(),
    args: zod.array(zod.unknown())
});
const logStackFrameSchema = zod.object({
    functionName: zod.string(),
    fileName: zod.string(),
    lineNumber: zod.number(),
    columnNumber: zod.number()
});
const levelSchema = zod["enum"]([
    'debug',
    'info',
    'warn',
    'error',
    'success'
]);
const logMeta = zod.object({
    stacktrace: zod.optional(zod.array(logStackFrameSchema)),
    logTraceID: zod.optional(zod.string()),
    skipFrame: zod.optional(zod.number()),
    noStacktrace: zod.optional(zod.boolean()),
    repairMessage: zod.optional(zod.string()),
    type: zod.optional(zod.string()),
    isDuplicate: zod.optional(zod.boolean()),
    duplicateCount: zod.optional(zod.number()),
    duplicateOfId: zod.optional(zod.string())
});
const selectedLogSchema = zod.object({
    type: zod.literal('typedLogV2'),
    level: levelSchema,
    id: zod.string(),
    args: zod.array(zod.unknown()),
    meta: logMeta
});
const logWithMetaSchema = zod.object({
    level: levelSchema,
    args: zod.array(zod.unknown()),
    meta: zod.optional(logMeta)
});
export { genericErrorSchema, levelSchema, logMeta, logStackFrameSchema, logWithMetaSchema, networkRequestLogSchema, noCategoryLogSchema, routerErrorSchema, selectedLogSchema };
